(function(root){'use strict';const DAY=864e5;
function analyze(events,c){const from=AB.date(c.from),to=AB.date(c.to),until=AB.date(c.until);if(from===null||to===null||until===null||from>to)throw Error('Chọn khoảng cohort và ngày quan sát hợp lệ.');if(!c.days?.length||c.days.some(n=>!Number.isInteger(n)||n<1||n>180))throw Error('Chọn ngày retention R1–R180.');if(!c.cohortEvent)throw Error('Nhập event tạo cohort.');if(c.segmentEvent&&c.segmentEvent===c.cohortEvent)throw Error('Event phân nhóm cần khác event tạo cohort.');const end=until+DAY,valid=events.filter(e=>e.time<end),users=new Map(),key=e=>JSON.stringify([e.dims.app,e.dims.platform,e.user]);for(const e of valid){if(e.event!==c.cohortEvent)continue;const k=key(e),d=AB.date(e.date);if(!users.has(k)||d<users.get(k).start)users.set(k,{start:d,cohort:e.date,exposed:false,active:new Set(),dims:e.dims})}for(const e of valid){const u=users.get(key(e));if(!u)continue;const d=AB.date(e.date);if(d<u.start)continue;if(e.event===c.segmentEvent&&d===u.start)u.exposed=true;if(!c.activeEvent||c.activeEvent==='*'||e.event===c.activeEvent)u.active.add((d-u.start)/DAY)}const cohort=[...users.values()].filter(u=>u.start>=from&&u.start<=to&&(!c.platform||u.dims.platform===c.platform)&&(!c.country||u.dims.country===c.country));const groups=c.segmentEvent?['all','yes','no']:['all'];const groupUsers=g=>cohort.filter(u=>g==='all'||u.exposed===(g==='yes'));const count=(arr,n)=>{const eligible=arr.filter(u=>u.start+n*DAY<=until),retained=eligible.filter(u=>u.active.has(n)).length;return {eligible:eligible.length,retained,rate:eligible.length?100*retained/eligible.length:null}};const overall=groups.map(group=>({group,users:groupUsers(group).length,points:c.days.map(day=>({day,...count(groupUsers(group),day)}))}));const dates=[...new Set(cohort.map(u=>u.cohort))].sort();const byCohort=dates.map(date=>({date,groups:groups.map(group=>({group,points:c.days.map(day=>({day,...count(groupUsers(group).filter(u=>u.cohort===date),day)}))}))}));return {users:cohort.length,overall,byCohort,from:c.from,to:c.to,until:c.until}}
const api={analyze};if(typeof module!=='undefined')module.exports=api;else root.Retention=api;
})(typeof window!=='undefined'?window:globalThis);
